{\n  @include visually-hidden();\n}\n","// stylelint-disable declaration-no-important\n\n// Hide content visually while keeping it accessible to assistive technologies\n//\n// See: https://www.a11yproject.com/posts/2013-01-11-how-to-hide-content/\n// See: https://hugogiraudel.com/2016/10/13/css-hide-and-seek/\n\n@mixin visually-hidden() {\n  position: absolute !important;\n  width: 1px !important;\n  height: 1px !important;\n  padding: 0 !important;\n  margin: -1px !important; // Fix for https://github.com/twbs/bootstrap/issues/25686\n  overflow: hidden !important;\n  clip: rect(0, 0, 0, 0) !important;\n  white-space: nowrap !important;\n  border: 0 !important;\n}\n\n// Use to only display content when it's focused, or one of its child elements is focused\n// (i.e. when focus is within the element/container that the class was applied to)\n//\n// Useful for \"Skip to main content\" links; see https://www.w3.org/TR/2013/NOTE-WCAG20-TECHS-20130905/G1\n\n@mixin visually-hidden-focusable() {\n  &:not(:focus):not(:focus-within) {\n    @include visually-hidden();\n  }\n}\n","//\n// Stretched link\n//\n\n.stretched-link {\n  &::#{$stretched-link-pseudo-element} {\n    position: absolute;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    left: 0;\n    z-index: $stretched-link-z-index;\n    content: \"\";\n  }\n}\n","//\n// Text truncation\n//\n\n.text-truncate {\n  @include text-truncate();\n}\n","// Text truncate\n// Requires inline-block or block for proper styling\n\n@mixin text-truncate() {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n",".vr {\n  display: inline-block;\n  align-self: stretch;\n  width: 1px;\n  min-height: 1em;\n  background-color: currentColor;\n  opacity: $hr-opacity;\n}\n","// Utility generator\n// Used to generate utilities & print utilities\n@mixin generate-utility($utility, $infix, $is-rfs-media-query: false) {\n  $values: map-get($utility, values);\n\n  // If the values are a list or string, convert it into a map\n  @if type-of($values) == \"string\" or type-of(nth($values, 1)) != \"list\" {\n    $values: zip($values, $values);\n  }\n\n  @each $key, $value in $values {\n    $properties: map-get($utility, property);\n\n    // Multiple properties are possible, for example with vertical or horizontal margins or paddings\n    @if type-of($properties) == \"string\" {\n      $properties: append((), $properties);\n    }\n\n    // Use custom class if present\n    $property-class: if(map-has-key($utility, class), map-get($utility, class), nth($properties, 1));\n    $property-class: if($property-class == null, \"\", $property-class);\n\n    // State params to generate pseudo-classes\n    $state: if(map-has-key($utility, state), map-get($utility, state), ());\n\n    $infix: if($property-class == \"\" and str-slice($infix, 1, 1) == \"-\", str-slice($infix, 2), $infix);\n\n    // Don't prefix if value key is null (eg. with shadow class)\n    $property-class-modifier: if($key, if($property-class == \"\" and $infix == \"\", \"\", \"-\") + $key, \"\");\n\n    @if map-get($utility, rfs) {\n      // Inside the media query\n      @if $is-rfs-media-query {\n        $val: rfs-value($value);\n\n        // Do not render anything if fluid and non fluid values are the same\n        $value: if($val == rfs-fluid-value($value), null, $val);\n      }\n      @else {\n        $value: rfs-fluid-value($value);\n      }\n    }\n\n    $is-css-var: map-get($utility, css-var);\n    $is-local-vars: map-get($utility, local-vars);\n    $is-rtl: map-get($utility, rtl);\n\n    @if $value != null {\n      @if $is-rtl == false {\n        /* rtl:begin:remove */\n      }\n\n      @if $is-css-var {\n        .#{$property-class + $infix + $property-class-modifier} {\n          --#{$variable-prefix}#{$property-class}: #{$value};\n        }\n\n        @each $pseudo in $state {\n          .#{$property-class + $infix + $property-class-modifier}-#{$pseudo}:#{$pseudo} {\n            --#{$variable-prefix}#{$property-class}: #{$value};\n          }\n        }\n      } @else {\n        .#{$property-class + $infix + $property-class-modifier} {\n          @each $property in $properties {\n            @if $is-local-vars {\n              @each $local-var, $value in $is-local-vars {\n                --#{$variable-prefix}#{$local-var}: #{$value};\n              }\n            }\n            #{$property}: $value if($enable-important-utilities, !important, null);\n          }\n        }\n\n        @each $pseudo in $state {\n          .#{$property-class + $infix + $property-class-modifier}-#{$pseudo}:#{$pseudo} {\n            @each $property in $properties {\n              #{$property}: $value if($enable-important-utilities, !important, null);\n            }\n          }\n        }\n      }\n\n      @if $is-rtl == false {\n        /* rtl:end:remove */\n      }\n    }\n  }\n}\n","// Loop over each breakpoint\n@each $breakpoint in map-keys($grid-breakpoints) {\n\n  // Generate media query if needed\n  @include media-breakpoint-up($breakpoint) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    // Loop over each utility property\n    @each $key, $utility in $utilities {\n      // The utility can be disabled with `false`, thus check if the utility is a map first\n      // Only proceed if responsive media queries are enabled or if it's the base media query\n      @if type-of($utility) == \"map\" and (map-get($utility, responsive) or $infix == \"\") {\n        @include generate-utility($utility, $infix);\n      }\n    }\n  }\n}\n\n// RFS rescaling\n@media (min-width: $rfs-mq-value) {\n  @each $breakpoint in map-keys($grid-breakpoints) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    @if (map-get($grid-breakpoints, $breakpoint) < $rfs-breakpoint) {\n      // Loop over each utility property\n      @each $key, $utility in $utilities {\n        // The utility can be disabled with `false`, thus check if the utility is a map first\n        // Only proceed if responsive media queries are enabled or if it's the base media query\n        @if type-of($utility) == \"map\" and map-get($utility, rfs) and (map-get($utility, responsive) or $infix == \"\") {\n          @include generate-utility($utility, $infix, true);\n        }\n      }\n    }\n  }\n}\n\n\n// Print utilities\n@media print {\n  @each $key, $utility in $utilities {\n    // The utility can be disabled with `false`, thus check if the utility is a map first\n    // Then check if the utility needs print styles\n    @if type-of($utility) == \"map\" and map-get($utility, print) == true {\n      @include generate-utility($utility, \"-print\");\n    }\n  }\n}\n","html, html a, body {\n  -webkit-font-smoothing: antialiased;\n}\n\na {\n  transition: all 0.3s ease-in-out;\n  text-decoration: none;\n}\n\nbody {\n  font-family: $font-primary;\n  font-size: 14px;\n  color: $default-text-color;\n  line-height: 1.5;\n  letter-spacing: 0.2px;\n  overflow-x: hidden;\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  font-family: $font-secondary;\n  letter-spacing: 0.5px;\n  line-height: 1.5;\n\n  a {\n    font-family: $font-secondary;\n  }\n\n  small {\n    font-weight: 300;\n    color: lighten($default-dark, 5%);\n  }\n}\n\np {\n  font-family: $font-primary;\n  line-height: 1.9;\n}\n\n.lead {\n  font-size: 18px;\n}\n\nul {\n  margin-bottom: 0;\n}\n\na {\n  color: $default-info;\n\n  &:hover,\n  &:focus {\n    text-decoration: none;\n    color: darken($default-info, 10%);\n  }\n\n  &:focus {\n    outline: none;\n  }\n\n  &.text-gray {\n    &:hover,\n    &:focus,\n    &.active {\n      color: $default-dark !important;\n    }\n  }\n}\n\n:focus {\n  outline: none;\n}\n\nhr {\n  border-top: 1px solid $border-color;\n}\n\n\na.btn {\n    color:#fff;\n  }\n\na.btn:hover {\n  color:#fff;\n}\n\n.btn-color {\n  color:#fff;\n}\n\n.btn-color:hover {\n  color:#fff;\n}\n","$font-primary:\n  Roboto, -apple-system, system-ui, BlinkMacSystemFont, \"Segoe UI\", \"Helvetica Neue\", Arial, sans-serif;\n$font-secondary: $font-primary;\n$font-size-base:              0.875rem;\n","// ---------------------------------------------------------\n// @TOC\n// ---------------------------------------------------------\n\n// + @Greyscale Colors\n// + @Bootstrap Color System\n// + @Default Colors\n// + @Inverted Colors\n// + @Others\n// + @Header Themes\n// + @Social Networks Colors\n\n// ---------------------------------------------------------\n// @Greyscale Colors\n// ---------------------------------------------------------\n\n// Colors below are ordered from lightest to darkest\n\n$grey-100             : #f9fafb;\n$grey-200             : #f2f3f5;\n$grey-300             : #e6eaf0;\n$grey-400             : #d3d9e3;\n$grey-500             : #b9c2d0;\n$grey-600             : #7c8695;\n$grey-700             : #72777a;\n$grey-800             : #565a5c;\n$grey-900             : #313435;\n\n$grey-colors-alt: (\n  grey-100 : #f9fafb,\n  grey-200 : #f2f3f5,\n  grey-300 : #e6eaf0,\n  grey-400 : #d3d9e3,\n  grey-500 : #b9c2d0,\n  grey-600 : #7c8695,\n  grey-700 : #72777a,\n  grey-800 : #565a5c,\n  grey-900 : #313435,\n);\n\n// ---------------------------------------------------------\n// @Bootstrap Color System\n// ---------------------------------------------------------\n\n$blue   : $md-blue-500;\n$indigo : $md-indigo-500;\n$purple : $md-purple-500;\n$pink   : $md-pink-500;\n$red    : $md-red-500;\n$orange : $md-orange-500;\n$yellow : $md-yellow-500;\n$green  : $md-green-500;\n$teal   : $md-teal-500;\n$cyan   : $md-cyan-500;\n\n// ---------------------------------------------------------\n// @Default Colors\n// ---------------------------------------------------------\n\n$default-danger       : #ff3c7e;\n$default-dark         : #313435;\n$default-grey         : #565a5c;\n$default-info         : #0f9aee;\n$default-primary      : #7774e7;\n$default-success      : #37c936;\n$default-text-color   : #72777a;\n$default-warning      : #fc0;\n$default-white        : #fff;\n\n// ---------------------------------------------------------\n// @Inverted Colors\n// ---------------------------------------------------------\n\n$inverse-danger       : lighten($default-danger, 35%);\n$inverse-info         : lighten($default-info, 45%);\n$inverse-primary      : lighten($default-primary, 30%);\n$inverse-success      : lighten($default-success, 45%);\n$inverse-warning      : lighten($default-warning, 45%);\n\n// ---------------------------------------------------------\n// @Others\n// ---------------------------------------------------------\n\n$border-color         : #e6ecf5;\n$collapsed-size       : 70px;\n$header-height        : 65px;\n$offscreen-size       : 280px;\n$side-nav-dark        : #313644;\n$side-nav-dark-border : rgba(120, 130, 140, 0.3);\n$side-nav-dark-font   : #99abb4;\n\n// ---------------------------------------------------------\n// @Header Themes\n// ---------------------------------------------------------\n\n$theme-danger         : #f53f61;\n$theme-dark           : lighten($side-nav-dark, 10%);\n$theme-info           : $default-info;\n$theme-primary        : $default-primary;\n$theme-success        : desaturate($default-success, 5%);\n","// ---------------------------------------------------------\n// @TOC\n// ---------------------------------------------------------\n\n// + @Sidebar\n// + @Sidebar Inner\n// + @Sidebar Header\n// + @Sidebar Menu\n// + @Sidebar Collapsed\n\n// ---------------------------------------------------------\n// @Sidebar\n// ---------------------------------------------------------\n\n.sidebar {\n  background-color: $default-white;\n  bottom: 0;\n  overflow: hidden;\n  position: fixed;\n  top: 0;\n  transition: all 0.2s ease;\n  width: $offscreen-size;\n  z-index: 1000;\n\n  ul {\n    list-style-type: none;\n  }\n\n  @include between($breakpoint-md, $breakpoint-xl) {\n    width: $collapsed-size;\n\n    .sidebar-inner {\n      .sidebar-logo {\n        border-bottom: 1px solid transparent;\n        padding: 0;\n\n        a {\n          .logo {\n            background-position: center center;\n            width: $collapsed-size;\n          }\n        }\n      }\n\n      .sidebar-menu {\n        overflow-x: hidden;\n\n        > li {\n          > a {\n            .title {\n              display: none;\n            }\n          }\n        }\n\n        li {\n          &.dropdown {\n            .arrow {\n              opacity: 0;\n            }\n\n            &.open {\n              ul.dropdown-menu {\n                display: none !important;\n              }\n            }\n          }\n        }\n      }\n    }\n\n    &:hover {\n      width: $offscreen-size;\n\n      .sidebar-inner {\n        .sidebar-logo {\n          border-bottom: 1px solid $border-color;\n          padding: 0 20px;\n        }\n\n        .sidebar-menu {\n          > li {\n            > a {\n              .title {\n                display: inline-block;\n              }\n            }\n          }\n\n          li {\n            &.dropdown {\n              .arrow {\n                opacity: 1;\n              }\n            }\n\n            &.open {\n              > ul.dropdown-menu {\n                display: block !important;\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n\n  @include to($breakpoint-md) {\n    left: -$offscreen-size;\n    width: calc(#{$offscreen-size} - 30px);\n  }\n}\n\n// ---------------------------------------------------------\n// @Sidebar Inner\n// ---------------------------------------------------------\n\n.sidebar-inner {\n  position: relative;\n  height: 100%;\n}\n\n// ---------------------------------------------------------\n// @Sidebar Header\n// ---------------------------------------------------------\n\n.sidebar-logo {\n  border-bottom: 1px solid $border-color;\n  border-right: 1px solid $border-color;\n  line-height: 0;\n  padding: 0 20px;\n  transition: all 0.2s ease;\n\n  a {\n    display: inline-block;\n    width: 100%;\n\n    .logo {\n      background-position: center left;\n      background-repeat: no-repeat;\n      display: inline-block;\n      min-height: calc(#{$header-height} - 1px);\n      width: 100%;\n      width: 70px;\n    }\n\n    .logo-text {\n      color: $grey-900;\n    }\n  }\n\n  .mobile-toggle {\n    display: none;\n    float: right;\n    font-size: 18px;\n    line-height: calc(#{$header-height} - 1px);\n\n    a {\n      color: $default-text-color;\n    }\n\n    @include to($breakpoint-md) {\n      display: inline-block;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      display: none;\n    }\n  }\n}\n\n// ---------------------------------------------------------\n// @Sidebar Menu\n// ---------------------------------------------------------\n\n.sidebar-menu {\n  @include clearfix;\n  border-right: 1px solid $border-color;\n  height: calc(100vh - #{$header-height});\n  list-style: none;\n  margin: 0;\n  overflow: auto;\n  padding: 0;\n  position: relative;\n\n  .dropdown-toggle::after {\n    display: none;\n  }\n\n  .sidebar-link {\n    &.actived::before {\n      background: $md-blue-500;\n      border-radius: 50%;\n      content: '';\n      display: block;\n      height: 8px;\n      left: -4px;\n      position: absolute;\n      top: calc(50% - 4px);\n      width: 8px;\n    }\n  }\n\n  li {\n    position: relative;\n\n    &.dropdown {\n      .arrow {\n        font-size: 10px;\n        line-height: 40px;\n        position: absolute;\n        right: 30px;\n        transition: all 0.05s ease-in;\n\n        @include to($breakpoint-md) {\n          right: 25px;\n        }\n      }\n\n      &.open {\n        > a {\n          color: $default-dark;\n\n          .icon-holder {\n            color: $default-info;\n          }\n\n          > .arrow {\n            transform: rotate(90deg);\n          }\n        }\n\n        > .dropdown-menu {\n          display: block;\n\n          .dropdown-menu {\n            padding-left: 20px;\n          }\n\n          .arrow {\n            line-height: 25px;\n          }\n        }\n      }\n    }\n\n    a {\n      color: $default-text-color;\n      transition: all 0.3s ease;\n\n      &:hover,\n      &:focus {\n        color: $default-dark;\n        text-decoration: none;\n\n        .icon-holder {\n          color: $default-info;\n        }\n      }\n    }\n  }\n\n  > li {\n    &.dropdown {\n      ul {\n        &.dropdown-menu {\n          background-color: transparent;\n          border-radius: 0;\n          border: 0;\n          box-shadow: none;\n          float: none;\n          padding-left: 50px;\n          padding-top: 0;\n          position: relative;\n          width: 100%;\n\n          > li {\n            > a {\n              display: block;\n              padding: 10px 15px;\n\n              &:hover,\n              &:focus {\n                background-color: transparent;\n                color: $default-dark;\n              }\n            }\n\n            &.actived {\n              a {\n                color: $default-dark;\n              }\n            }\n          }\n        }\n      }\n    }\n\n    > a {\n      display: block;\n      font-size: 15px;\n      font-weight: 500;\n      padding: 5px 15px;\n      position: relative;\n      white-space: nowrap;\n\n      .icon-holder {\n        border-radius: 6px;\n        display: inline-block;\n        font-size: 17px;\n        height: 35px;\n        left: 0;\n        line-height: 35px;\n        margin-right: 14px;\n        position: relative;\n        text-align: center;\n        transition: all 0.3s ease;\n        width: 35px;\n      }\n    }\n  }\n}\n\n// ---------------------------------------------------------\n// @Sidebar Collapsed\n// ---------------------------------------------------------\n\n.is-collapsed {\n  .sidebar {\n    @include from($breakpoint-xl) {\n      width: $collapsed-size;\n\n      .sidebar-inner {\n        .sidebar-logo {\n          border-bottom: 1px solid transparent;\n          padding: 0;\n        }\n\n        .sidebar-menu {\n          overflow-x: hidden;\n\n          > li {\n            > a {\n              .title {\n                display: none;\n              }\n            }\n          }\n\n          li {\n            &.dropdown {\n              .arrow {\n                opacity: 0;\n              }\n\n              &.open {\n                ul.dropdown-menu {\n                  display: none !important;\n                }\n              }\n            }\n          }\n        }\n      }\n\n      &:hover {\n        width: $offscreen-size;\n\n        .sidebar-inner {\n          .sidebar-logo {\n            border-bottom: 1px solid $border-color;\n            padding: 0 20px;\n          }\n\n          .sidebar-menu {\n            > li {\n              > a {\n                .title {\n                  display: inline-block;\n                }\n              }\n            }\n\n            li {\n              &.dropdown {\n                .arrow {\n                  opacity: 1;\n                }\n              }\n\n              &.open {\n                > ul.dropdown-menu {\n                  display: block !important;\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      width: $offscreen-size;\n\n      .sidebar-inner {\n        .sidebar-logo {\n          border-bottom: 1px solid $border-color;\n          padding: 0 20px;\n\n          > a {\n            .logo {\n              background-position: center left;\n              width: 150px;\n            }\n          }\n        }\n\n        .sidebar-menu {\n          > li {\n            > a {\n              .title {\n                display: inline-block;\n              }\n            }\n          }\n\n          li {\n            &.dropdown {\n              .arrow {\n                opacity: 1;\n              }\n            }\n\n            &.open {\n              > ul.dropdown-menu {\n                display: block !important;\n              }\n            }\n          }\n        }\n      }\n    }\n\n    @include to($breakpoint-md) {\n      left: 0;\n    }\n  }\n}\n","// ---------------------------------------------------------\n// @TOC\n// ---------------------------------------------------------\n\n// + @General Media Query\n// + @All Above Media Query\n// + @All Under Media Query\n// + @Between Two Devices Media Query\n\n// ---------------------------------------------------------\n// @General Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used for custom rules that don't follow\n// any of the following premade media queries.\n\n@mixin mq($condition) {\n  @media #{$condition} {\n    @content;\n  }\n}\n\n// ---------------------------------------------------------\n// @All Above Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used to match certain breakpoint\n// and all devices above it.\n\n@mixin from($breakpoint) {\n  @media screen and (min-width: $breakpoint){\n    @content;\n  }\n}\n\n// ---------------------------------------------------------\n// @All Under Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used to match all devices under certain breakpoint.\n\n@mixin to($breakpoint) {\n  @media screen and (max-width: $breakpoint - 1px) {\n    @content;\n  }\n}\n\n// ---------------------------------------------------------\n// @Between Two Devices Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used to match the devices between 2 breakpoints.\n\n@mixin between($start, $end){\n  @media screen and (min-width: $start) and (max-width: $end - 1px) {\n    @content;\n  }\n}\n","// ---------------------------------------------------------\n// @TOC\n\n// + @Topbar\n// + @Collapsed State\n\n// ---------------------------------------------------------\n// @Topbar\n// ---------------------------------------------------------\n\n.header {\n  background-color: $default-white;\n  border-bottom: 1px solid $border-color;\n  display: block;\n  margin-bottom: 0;\n  padding: 0;\n  position: fixed;\n  transition: all 0.2s ease;\n  width: calc(100% - #{$offscreen-size});\n  z-index: 800;\n\n  @include to($breakpoint-md) {\n    width: 100%;\n  }\n\n  @include between($breakpoint-md, $breakpoint-xl) {\n    width: calc(100% - #{$collapsed-size});\n  }\n\n  .header-container {\n    @include clearfix;\n\n    height: $header-height;\n\n    .nav-left,\n    .nav-right {\n      list-style: none;\n      margin-bottom: 0;\n      padding-left: 0;\n      position: relative;\n\n      > li {\n        float: left;\n\n        > a {\n          color: $default-text-color;\n          display: block;\n          line-height: $header-height;\n          min-height: $header-height;\n          padding: 0 15px;\n          transition: all 0.2s ease-in-out;\n\n          i {\n            font-size: 17px;\n          }\n\n          &:hover,\n          &:focus {\n            color: $default-dark;\n            text-decoration: none;\n          }\n\n          @include to($breakpoint-md) {\n            padding: 0 15px;\n          }\n        }\n      }\n\n      .notifications {\n        position: relative;\n\n        .counter {\n          background-color: $default-danger;\n          border-radius: 50px;\n          color: $default-white;\n          font-size: 10px;\n          line-height: 1;\n          padding: 3px 5.5px;\n          position: absolute;\n          right: 6px;\n          top: 12px;\n        }\n\n        .dropdown-menu {\n          min-width: 350px;\n          padding: 0;\n\n          @include to($breakpoint-sm) {\n            max-width: 300px;\n          }\n        }\n      }\n    }\n\n    .dropdown-menu {\n      // display: block;\n      margin: 0;\n      transform-origin: top right;\n      // transform: scale(0, 0);\n      transition: transform 0.15s ease-out;\n\n      .divider {\n        border-bottom: 1px solid $border-color;\n        height: 1px;\n        overflow: hidden;\n      }\n\n      > li {\n        > a {\n          transition: all 0.2s ease-out;\n        }\n      }\n    }\n\n    .show {\n      .dropdown-menu {\n        transform: scale(1, 1);\n      }\n    }\n\n    .nav-left {\n      float: left;\n      margin-left: 15px;\n    }\n\n    .nav-right {\n      float: right;\n\n      .dropdown-menu {\n        left: auto;\n        right: 0;\n\n        > li {\n          width: 100%;\n\n          > a {\n            line-height: 1.5;\n            min-height: auto;\n            padding: 10px 15px;\n          }\n        }\n      }\n    }\n  }\n\n  .search-box {\n    .search-icon-close {\n      display: none;\n    }\n\n    &.active {\n      .search-icon {\n        display: none;\n      }\n\n      .search-icon-close {\n        display: inline-block;\n      }\n    }\n  }\n\n  .search-input {\n    display: none;\n\n    &.active {\n      display: inline-block;\n    }\n\n    input {\n      background-color: transparent;\n      border: 0;\n      box-shadow: none;\n      font-size: 18px;\n      height: 40px;\n      margin-top: 12px;\n      outline: none;\n      padding: 5px;\n\n      @include to($breakpoint-sm) {\n        width: 85px;\n      }\n\n      @include placeholder {\n        color: lighten($default-text-color, 20%);\n        font-style: italic;\n      }\n    }\n  }\n}\n\n// ---------------------------------------------------------\n// @Collapsed State\n// ---------------------------------------------------------\n\n.is-collapsed {\n  .header {\n    width: calc(100% - #{$collapsed-size});\n\n    @include to($breakpoint-md) {\n      width: 100%;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      width: calc(100% - #{$offscreen-size});\n    }\n  }\n}\n","//----------------------------------------------------------\n// @Placeholder\n//----------------------------------------------------------\n\n@mixin placeholder {\n  &::-webkit-input-placeholder { @content; }\n  &:-moz-placeholder { @content; }\n  &::-moz-placeholder { @content; }\n  &:-ms-input-placeholder { @content; }\n}\n","// ---------------------------------------------------------\n// @TOC\n// ---------------------------------------------------------\n\n// + @Page Container\n// + @Main Content\n// + @Full Container\n// + @Collapsed State\n\n// ---------------------------------------------------------\n// @Page Container\n// ---------------------------------------------------------\n\n.page-container {\n  min-height: 100vh;\n  padding-left: $offscreen-size;\n  transition: all 0.2s ease;\n\n  @include between($breakpoint-md, $breakpoint-xl) {\n    padding-left: $collapsed-size;\n  }\n\n  @include to($breakpoint-md) {\n    padding-left: 0;\n  }\n}\n\n// ---------------------------------------------------------\n// @Main Content\n// ---------------------------------------------------------\n\n.main-content {\n  padding: 85px 20px 20px;\n  min-height: calc(100vh - 61px);\n\n  @include to($breakpoint-md) {\n    padding: 85px 5px 5px;\n  }\n}\n\n.remain-height {\n  height: calc(100vh - 126px);\n}\n\n// ---------------------------------------------------------\n// @Full Container\n// ---------------------------------------------------------\n\n.full-container {\n  left: $offscreen-size;\n  min-height: calc(100vh - #{$header-height});\n  position: absolute;\n  right: 0;\n  top: $header-height;\n  transition: all 0.2s ease;\n\n  @include between($breakpoint-md, $breakpoint-xl) {\n    left: 0;\n    padding-left: $collapsed-size;\n  }\n\n  @include to($breakpoint-md) {\n    left: 0;\n  }\n}\n\n// ---------------------------------------------------------\n// @Collapsed State\n// ---------------------------------------------------------\n\n.is-collapsed {\n  .page-container {\n    padding-left: $collapsed-size;\n\n    @include to($breakpoint-md) {\n      padding-left: 0;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      padding-left: $offscreen-size;\n    }\n  }\n\n  .full-container {\n    left: $collapsed-size;\n\n    @include to($breakpoint-md) {\n      left: 0;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      left: $offscreen-size;\n      padding-left: 0;\n    }\n  }\n}\n",".progress {\n  height: 4px;\n  background-color: #eaeef3;\n  border-radius: 4px;\n  margin-bottom: 10px;\n}\n",".easy-pie-chart {\n  position: relative;\n\n  span {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    line-height: 0;\n  }\n}\n",".checkbox label {\n  display: inline-block;\n  vertical-align: middle;\n  position: relative;\n  padding-left: 17px;\n  margin-bottom: 0;\n}\n\n.checkbox label::before {\n  content: \"\";\n  display: inline-block;\n  position: absolute;\n  width: 17px;\n  height: 17px;\n  left: 0;\n  top: 50%;\n  transform: translateY(-50%);\n  margin-left: -12px;\n  border: 1px solid $grey-300;\n  border-radius: 3px;\n  background-color: $md-white;\n  -webkit-transition: border 0.15s ease-in-out, color 0.15s ease-in-out;\n  -o-transition: border 0.15s ease-in-out, color 0.15s ease-in-out;\n  transition: border 0.15s ease-in-out, color 0.15s ease-in-out;\n}\n\n.checkbox label::after {\n  display: inline-block;\n  position: absolute;\n  width: 17px;\n  height: 17px;\n  text-align: center;\n  font-size: 10px !important;\n  line-height: 17px;\n  left: 0;\n  top: 50%;\n  transform: translateY(-50%);\n  margin-left: -12px;\n  color: $grey-500;\n}\n\n.checkbox input[type=\"checkbox\"] {\n  opacity: 0;\n  z-index: 1;\n}\n\n.checkbox input[type=\"checkbox\"]:focus + label::before {\n  outline: thin dotted;\n  outline: 5px auto -webkit-focus-ring-color;\n  outline-offset: -2px;\n}\n\n.checkbox input[type=\"checkbox\"]:checked + label::after {\n  font-family: 'FontAwesome';\n  content: \"\\f00c\";\n  font-size: 13px;\n}\n\n.checkbox input[type=\"checkbox\"]:disabled + label {\n  opacity: 0.65;\n}\n\n.checkbox input[type=\"checkbox\"]:disabled + label::before {\n  background-color: $grey-400;\n  cursor: not-allowed;\n}\n\n.checkbox.checkbox-circle label::before {\n  border-radius: 50%;\n}\n\n.checkbox.checkbox-inline {\n  margin-top: 0;\n}\n\n.checkbox-primary input[type=\"checkbox\"]:checked + label::before {\n  background-color: $default-primary;\n  border-color: $default-primary;\n}\n\n.checkbox-primary input[type=\"checkbox\"]:checked + label::after {\n  color: #fff;\n}\n\n.checkbox-danger input[type=\"checkbox\"]:checked + label::before {\n  background-color: $default-danger;\n  border-color: $default-danger;\n}\n\n.checkbox-danger input[type=\"checkbox\"]:checked + label::after {\n  color: $md-white;\n}\n\n.checkbox-info input[type=\"checkbox\"]:checked + label::before {\n  background-color: $default-info;\n  border-color: $default-info;\n}\n\n.checkbox-info input[type=\"checkbox\"]:checked + label::after {\n  color: $md-white;\n}\n\n.checkbox-warning input[type=\"checkbox\"]:checked + label::before {\n  background-color: $default-warning;\n  border-color: $default-warning;\n}\n\n.checkbox-warning input[type=\"checkbox\"]:checked + label::after {\n  color: $md-white;\n}\n\n.checkbox-success input[type=\"checkbox\"]:checked + label::before {\n  background-color: $default-success;\n  border-color: $default-success;\n}\n\n.checkbox-success input[type=\"checkbox\"]:checked + label::after {\n  color: $md-white;\n}\n\n.radio {\n  padding-left: 20px;\n}\n\n.radio label {\n  display: inline-block;\n  vertical-align: middle;\n  position: relative;\n  padding-left: 5px;\n}\n\n.radio label::before {\n  content: \"\";\n  display: inline-block;\n  position: absolute;\n  width: 17px;\n  height: 17px;\n  left: 0;\n  margin-left: -20px;\n  border: 1px solid #cccccc;\n  border-radius: 50%;\n  background-color: #fff;\n  -webkit-transition: border 0.15s ease-in-out;\n  -o-transition: border 0.15s ease-in-out;\n  transition: border 0.15s ease-in-out;\n}\n\n.radio label::after {\n  display: inline-block;\n  position: absolute;\n  content: \" \";\n  width: 11px;\n  height: 11px;\n  left: 3px;\n  top: 3px;\n  margin-left: -20px;\n  border-radius: 50%;\n  background-color: #555555;\n  -webkit-transform: scale(0, 0);\n  -ms-transform: scale(0, 0);\n  -o-transform: scale(0, 0);\n  transform: scale(0, 0);\n  -webkit-transition: -webkit-transform 0.1s cubic-bezier(0.8, -0.33, 0.2, 1.33);\n  -moz-transition: -moz-transform 0.1s cubic-bezier(0.8, -0.33, 0.2, 1.33);\n  -o-transition: -o-transform 0.1s cubic-bezier(0.8, -0.33, 0.2, 1.33);\n  transition: transform 0.1s cubic-bezier(0.8, -0.33, 0.2, 1.33);\n}\n\n.radio input[type=\"radio\"] {\n  opacity: 0;\n  z-index: 1;\n}\n\n.radio input[type=\"radio\"]:focus + label::before {\n  outline: thin dotted;\n  outline: 5px auto -webkit-focus-ring-color;\n  outline-offset: -2px;\n}\n\n.radio input[type=\"radio\"]:checked + label::after {\n  -webkit-transform: scale(1, 1);\n  -ms-transform: scale(1, 1);\n  -o-transform: scale(1, 1);\n  transform: scale(1, 1);\n}\n\n.radio input[type=\"radio\"]:disabled + label {\n  opacity: 0.65;\n}\n\n.radio input[type=\"radio\"]:disabled + label::before {\n  cursor: not-allowed;\n}\n\n.radio.radio-inline {\n  margin-top: 0;\n}\n\n.radio-primary input[type=\"radio\"] + label::after {\n  background-color: #428bca;\n}\n\n.radio-primary input[type=\"radio\"]:checked + label::before {\n  border-color: #428bca;\n}\n\n.radio-primary input[type=\"radio\"]:checked + label::after {\n  background-color: #428bca;\n}\n\n.radio-danger input[type=\"radio\"] + label::after {\n  background-color: #d9534f;\n}\n\n.radio-danger input[type=\"radio\"]:checked + label::before {\n  border-color: #d9534f;\n}\n\n.radio-danger input[type=\"radio\"]:checked + label::after {\n  background-color: #d9534f;\n}\n\n.radio-info input[type=\"radio\"] + label::after {\n  background-color: #5bc0de;\n}\n\n.radio-info input[type=\"radio\"]:checked + label::before {\n  border-color: #5bc0de;\n}\n\n.radio-info input[type=\"radio\"]:checked + label::after {\n  background-color: #5bc0de;\n}\n\n.radio-warning input[type=\"radio\"] + label::after {\n  background-color: #f0ad4e;\n}\n\n.radio-warning input[type=\"radio\"]:checked + label::before {\n  border-color: #f0ad4e;\n}\n\n.radio-warning input[type=\"radio\"]:checked + label::after {\n  background-color: #f0ad4e;\n}\n\n.radio-success input[type=\"radio\"] + label::after {\n  background-color: #5cb85c;\n}\n\n.radio-success input[type=\"radio\"]:checked + label::before {\n  border-color: #5cb85c;\n}\n\n.radio-success input[type=\"radio\"]:checked + label::after {\n  background-color: #5cb85c;\n}\n","#loader {\n  transition: all 0.3s ease-in-out;\n  opacity: 1;\n  display: default;\n}\n\n#loader.fadeOut {\n  opacity: 0;\n  display: none;\n}\n\n\n\n.spinner {\n  width: 40px;\n  height: 40px;\n  position: absolute;\n  top: calc(50% - 20px);\n  left: calc(50% - 20px);\n  background-color: #333;\n  border-radius: 100%;\n  -webkit-animation: sk-scaleout 1.0s infinite ease-in-out;\n  animation: sk-scaleout 1.0s infinite ease-in-out;\n}\n\n@-webkit-keyframes sk-scaleout {\n  0% { -webkit-transform: scale(0) }\n  100% {\n    -webkit-transform: scale(1.0);\n    opacity: 0;\n  }\n}\n\n@keyframes sk-scaleout {\n  0% {\n    -webkit-transform: scale(0);\n    transform: scale(0);\n  } 100% {\n    -webkit-transform: scale(1.0);\n    transform: scale(1.0);\n    opacity: 0;\n  }\n}\n","footer {\n  z-index: 1;\n  position: relative;\n}\n","#chat-sidebar {\n  width: 250px;\n  height: calc(100vh - #{$header-height} - 60px);\n  overflow: auto;\n\n  @include to($breakpoint-md) {\n    transition: all 0.3s ease-in-out;\n    margin-left: -250px;\n\n    &.open {\n      margin-left: 0;\n    }\n  }\n}\n\n#chat-box {\n  height: calc(100vh - #{$header-height} - 60px);\n  overflow: auto;\n}\n",".email-app {\n  .email-side-nav {\n    background: $default-white;\n    position: fixed;\n    border-right: 1px solid $border-color;\n    float: left;\n    width: 250px;\n    transition: all 0.3s ease-in-out;\n\n    @include to($breakpoint-